// ============================================================
// §6 流量统计（模块 7）
// ============================================================
//
// 🔴 **口径：`stat_user_server.stat_date` 是按 `Asia/Shanghai` 切的天**（0009:18 的列注释，
//
//	写入侧 stats.sql 的 `BulkUpsertStatUserServer` 用的就是 `(now() AT TIME ZONE 'Asia/Shanghai')::date`）。
//	所以本节的入参必须做同样的换算：`(:from AT TIME ZONE 'Asia/Shanghai')::date`。
//	直接拿 UTC 日期去比会**整体错开一天**（UTC 的 8 月 29 日 20:00 属于上海的 8 月 30 日），
//	而错开一天的日报看起来完全正常 —— 只是每天的数字都是隔壁那天的。
//
// 🔴 **返回的是 `stat_date`（date）不是 `record_at`（timestamptz）**，与既有的
//
//	`GetGlobalDailyTraffic` 保持同一形状。openapi 的 `StatBucket.record_at` 是 date-time，
//	换算（上海当天 00:00 → UTC）必须在 handler 里用**同一个**辅助函数完成，
//	三种 scope 各写一遍是三份会漂移的时区代码。
//
// ⚠️ **openapi 给 `/admin/stats` 的参数里没有任何分页**（只有 scope/from/to）。
//
//	而 scope=user 的结果是「天数 × 用户数」行 —— 一年 × 1000 人 = 36.5 万行。
//	所以本节两条查询都带 `page_limit`，由 handler 钉死一个上限（建议 5000）并在命中上限时
//	**明确告诉调用方结果被截断**。静默截断的报表会被当成完整数据去做决策。
//
// ⚠️ `exportAdminStats`（D14）复用本节的同三条查询，不另写：CSV 与 JSON 的差别在序列化层。
//
//	D14 的审计走 `audit.Write`（纯读操作没有业务事务可搭，audit.go 明写这是保留 Write 导出的理由）。
//	⚠️ 但 `/admin/stats/export` 的参数**只有 scope，没有 from/to** —— handler 必须自己钉一个
//	有界窗口（建议最近 90 天）。无界导出 = 一次请求带走全站历史，D14 那层权限位就白设了。
//
// ⚠️ 这两条导出的是 user_id / server_id，**不含邮箱** —— 统计导出的泄漏面因此比
//
//	§1.7 的用户导出小一个量级。这不是巧合：StatBucket 的字段就是这么定的，不要为了
//	「CSV 好看」去 JOIN 一个 email 进来。
//
// 按用户分桶（scope=user）。走 `stat_user` 视图（= stat_user_server 按 (user_id, stat_date) 聚合），
// 视图恒等于实表，不多存一份数字（0009 的裁决）。
// ⚠️ 排序用 (stat_date DESC, user_id)：报表默认看最近的几天；user_id 破平手让分页/截断确定。
func (q *Queries) ListAdminStatByUser(ctx context.Context, arg ListAdminStatByUserParams) ([]ListAdminStatByUserRow, error) {
	rows, err := q.db.Query(ctx, listAdminStatByUser,
		arg.FromAt,
		arg.ToAt,
		arg.UserID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAdminStatByUserRow{}
	for rows.Next() {
		var i ListAdminStatByUserRow
		if err := rows.Scan(
			&i.StatDate,
			&i.UserID,
			&i.UploadBytes,
			&i.DownloadBytes,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listAdminUsersPage = `-- name: ListAdminUsersPage :many



SELECT
  u.id, u.email, u.banned, u.banned_reason, u.banned_at,
  u.plan_id, p.name AS plan_name, u.group_id,
  u.expired_at, u.sub_revoked_at, u.device_limit, u.speed_limit_mbps,
  u.transfer_enable_plan, u.transfer_enable_pack, u.transfer_enable,
  u.invited_by, u.last_login_at, u.created_at,
  coalesce(ut.u, 0)::bigint  AS upload_bytes,
  coalesce(ut.d, 0)::bigint  AS download_bytes,
  coalesce(wb.balance, 0)::bigint AS balance_amount
FROM users u
LEFT JOIN user_traffic    ut ON ut.user_id = u.id
LEFT JOIN plans           p  ON p.id       = u.plan_id
LEFT JOIN wallet_balances wb ON wb.user_id = u.id
WHERE u.deleted_at IS NULL
  AND ($1::text IS NULL OR u.email ILIKE $1::text)
  AND ($2::boolean  IS NULL OR u.banned  = $2::boolean)
  AND ($3::bigint  IS NULL OR u.plan_id = $3::bigint)
  AND ($4::bigint IS NULL OR u.id < $4::bigint)
ORDER BY u.id DESC
LIMIT $5::integer
`

