// admin_accounts.sql · 管理面：用户 / 管理员 / 邀请返佣 / 审计 / 配置 / 统计 / 公告
//
// 事实源：openapi/openapi.yaml（已冻结）里的 25 个 operationId ——
//
//	getAdminDashboard · listAdminUsers · getAdminUser · updateAdminUser · banAdminUser ·
//	unbanAdminUser · revokeAdminUserSubscriptions · exportAdminUsers · adjustAdminUserBalance ·
//	getAdminStats · exportAdminStats · listAdminInvites · createAdminInvite ·
//	adjustAdminCommission · listAdminAuditLog · listAdmins · createAdmin · deleteAdmin ·
//	resetAdminTotp · listAdminNotices · createAdminNotice · updateAdminNotice ·
//	deleteAdminNotice · getAdminSettings · updateAdminSettings；
//	api-contract.md §2.4（分页）· §6.1（17 个模块）· §6.2（D1–D16 四层强制）· §6.3（审计三条硬规则）；
//	data-model.md §1.2 裁决 8（users 永不硬删）· §7.1（余额的唯一真相是分录）· §11.1（append-only）；
//	ADR 0013 §3.5 / §5.2（余额分可提现/不可提现、配额拆两个分量列）；
//	列名逐列核自 0002_foundation · 0003_accounts · 0005_online_state · 0006_orders ·
//	0007_ledger · 0009_stats · 0010_tickets · 0011_ops · 0015_payment_fixes · 0016_billing_rules。
//
// ============================================================
// 🔴 写这一组查询前必须先接受的五条
// ============================================================
//
//  1. **`users.transfer_enable` 是 GENERATED ALWAYS AS (_plan + _pack) STORED，不可赋值**
//     （0016:66）。写它 sqlc generate 与 go build 都是 exit 0，只在运行时炸
//     （ADR 0013 §6.3 实测）。本文件里任何改配额的语句写的都是 `transfer_enable_plan`。
//
//  2. **users 永不硬删**（data-model §1.2 裁决 8）。本文件里没有一条 `DELETE FROM users`。
//     「删除账号」是 users.sql 的 `AnonymizeUser`；而 `deleteAdmin` 删的是 **admin_users**，
//     是完全不同的一件事 —— 两者唯一的共同点是名字里都有「删」字。
//
//  3. **审计要改前/改后两个值**（§6.3 第 2 条：存完整快照不存 diff）。
//     本文件统一用**一条语句里的 before/after CTE**，而不是「先读一份再改」。
//     理由写在 §1.5 的 `UpdateAdminUserEntitlement` 上，其余各处只引用不重复。
//
//  4. **L1 确认串的比对在 API 层**（§6.2）。所以凡是标 🔒 的操作，本文件都提供一条
//     「先把目标标识串查出来并锁住」的查询（`LockAdminUserTarget` / `LockAdminAccountTarget`），
//     handler 必须先跑它、常数时间比对、再动手。前端弹窗对 `curl` 是零。
//
// 5. **金额一律 bigint 人民币分，流量一律 bigint 字节。禁止浮点**（api-contract §2.6）。
//
// ============================================================
// ℹ️ 刻意**不重写**的既有查询（handler 直接复用，逐条点名）
// ============================================================
//
// · `subscription_user.sql` 的 **RevokeAllUserSubscriptionTokens** —— D3 的写就是它。
//
//	它用「数据修改型 CTE 互相看不到对方效果」这条语义算出「本次真正撤掉几条」，
//	重写一遍只会多一处会漂移的副本。D3 的**改前值**从 `LockAdminUserTarget` 那一次读里来
//	（L1 本来就必须先读一次目标，两件事合成一条查询，见 §1.4）。
//
// · `wallet.sql` 的 **GetWalletOverview** —— D10 调余额的改前/改后两个快照都用它，
//
//	在同一个事务里前后各跑一次。它返回的三个数正好是 openapi `Wallet` 的 required 三项。
//
// · `orders.sql` 的 **CreateLedgerEntry / CreateLedgerLine / UpsertWalletBalance** —— D10 的分录三步。
// · `stats.sql` 的 **GetGlobalDailyTraffic** —— getAdminStats 的 `scope=global` 就是它，
//
//	本文件只补 `scope=user` 与 `scope=server` 两个**跨实体**聚合（既有的那两条是单实体的）。
//
// · `users.sql` 的 **BanUser / UnbanUser** —— ⚠️ **管理面不要用它们**：它们 `RETURNING *`
//
//	给的只有改后值，D2 要的改前值拿不到。管理面走本文件的 `AdminBanUser` / `AdminUnbanUser`。
//
// · `users.sql` 的 **ListUsersForAdmin / CountUsersForAdmin** —— ⚠️ **同样不要用**：
//
//	它们是 `LIMIT/OFFSET`，而 openapi 给 listAdminUsers 的是 CursorQuery（§2.4）。
//	OFFSET 在一张持续新增的表上翻页会**漏行**，且漏的方式没有任何报错。
//
// ============================================================
// §1 用户管理（模块 2）
// ============================================================
// ---------- §1.1 用户列表（listAdminUsers） ----------
//
// 游标分页（api-contract §2.4）。游标只用 `id`，不用 (created_at, id)：
// `users.id` 是 IDENTITY 列，单键即全序，与 wallet.sql §2 的取舍同源。
// 代价登记：id 序与 created_at 序在**并发插入**下可能差几行（id 先取号后提交），
// 但两者都是全序，翻页不重不漏 —— 而这正是游标唯一要保证的事。
//
// 🔴 **`user_traffic` 用 LEFT JOIN，不是 JOIN**（users.sql 的 `ListUsersForAdmin` 用的是 JOIN）。
//
//	1:1 拆表由 `CreateUser` + `CreateUserTraffic` 同事务建立，理论上不会缺行；
//	但一旦缺了（手工插过一行、DR 从半份备份恢复），JOIN 会让那个用户**从后台列表里消失**。
//	用户面少一条只是少一条，管理面少一条是「这个人不存在」的假象 ——
//	而管理员会据此去回复工单。宁可显示两个 0。
//
// ⚠️ `q` 走 `email ILIKE`，没有 trigram 索引，是一次顺序扫描。用户量到万级之前这是零成本，
//
//	再往上要么加 `pg_trgm` + GIN，要么把搜索限制成前缀匹配（`email ILIKE q || '%'` 能吃到
//	`users_email_uk` 的函数索引，但只有在 handler 也 lower() 之后）。**撤回条件**：
//	本条 p95 > 200 ms。
//
// 🔴 `q` 是**用户输入**，handler 必须先转义 LIKE 元字符 `\` `%` `_` 再拼 `%…%`。
//
//	不转义时一个 `%` 就等于「返回全部用户」，而这个端点的下游是 D14 的同一批数据。
//
// ⚠️ balance_amount 取 `wallet_balances`（缓存表）而不是扫分录：列表一次要算 20 个人的余额，
//
//	按 data-model §7.1「面板每次打开都要读余额，不能每次扫分录」，列表就是那条规则的正例。
//	**钱要动的时候读分录**（D10 走 GetWalletOverview），列表只是展示。
func (q *Queries) ListAdminUsersPage(ctx context.Context, arg ListAdminUsersPageParams) ([]ListAdminUsersPageRow, error) {
	rows, err := q.db.Query(ctx, listAdminUsersPage,
		arg.EmailLike,
		arg.Banned,
		arg.PlanID,
		arg.CursorID,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListAdminUsersPageRow{}
	for rows.Next() {
		var i ListAdminUsersPageRow
		if err := rows.Scan(
			&i.ID,
			&i.Email,
			&i.Banned,
			&i.BannedReason,
			&i.BannedAt,
			&i.PlanID,
			&i.PlanName,
			&i.GroupID,
			&i.ExpiredAt,
			&i.SubRevokedAt,
			&i.DeviceLimit,
			&i.SpeedLimitMbps,
			&i.TransferEnablePlan,
			&i.TransferEnablePack,
			&i.TransferEnable,
			&i.InvitedBy,
			&i.LastLoginAt,
			&i.CreatedAt,
			&i.UploadBytes,
			&i.DownloadBytes,
			&i.BalanceAmount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockAdminAccountTarget = `-- name: LockAdminAccountTarget :one
SELECT a.id, a.email, a.role, a.disabled_at, a.totp_confirmed_at, a.created_at
FROM admin_users a
WHERE a.id = $1::bigint
FOR UPDATE
`

type LockAdminAccountTargetRow struct {
	ID              int64              `json:"id"`
	Email           string             `json:"email"`
	Role            string             `json:"role"`
	DisabledAt      pgtype.Timestamptz `json:"disabled_at"`
	TotpConfirmedAt pgtype.Timestamptz `json:"totp_confirmed_at"`
	CreatedAt       pgtype.Timestamptz `json:"created_at"`
}

// ---------- §2.2 L1 确认串 + 行锁（deleteAdmin / resetAdminTotp 的必经前置） ----------
//
// 与 §1.3 同形，理由不重复。管理员侧独有的一条：
// 🔴 **不要用请求里的 id 去猜 email，也不要让前端把 email 传上来当 confirmation 的比对基准**。
//
//	D16 的 `confirmation` 必须等于**服务端查出来的**那个 email。
//	这条查询就是「服务端自己查出来」那一步，少了它 L1 就是装饰。
//
// ⚠️ 不带 `disabled_at IS NULL`：对一个已停用的管理员再跑一次 reset-totp 是合理的
//
//	（停用期间换钥匙，恢复时直接可用）；而对已停用的再跑一次 delete 是幂等的空操作，
//	由 §2.4 自己的 CTE 处理成 (disabled → disabled)。
func (q *Queries) LockAdminAccountTarget(ctx context.Context, adminID int64) (LockAdminAccountTargetRow, error) {
	row := q.db.QueryRow(ctx, lockAdminAccountTarget, adminID)
	var i LockAdminAccountTargetRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Role,
		&i.DisabledAt,
		&i.TotpConfirmedAt,
		&i.CreatedAt,
	)
	return i, err
}

const lockAdminUserTarget = `-- name: LockAdminUserTarget :one
SELECT u.id, u.email, u.banned, u.sub_revoked_at, u.plan_id, u.expired_at, u.created_at
FROM users u
WHERE u.id = $1::bigint AND u.deleted_at IS NULL
FOR UPDATE
`

type LockAdminUserTargetRow struct {
	ID           int64              `json:"id"`
	Email        string             `json:"email"`
	Banned       bool               `json:"banned"`
	SubRevokedAt pgtype.Timestamptz `json:"sub_revoked_at"`
	PlanID       *int64             `json:"plan_id"`
	ExpiredAt    pgtype.Timestamptz `json:"expired_at"`
	CreatedAt    pgtype.Timestamptz `json:"created_at"`
}

// ---------- §1.3 L1 确认串 + 行锁（D3 撤订阅 / D10 调余额的**必经前置**） ----------
//
// 🔴 **一条查询同时干三件事，三件都是必须的**：
//  1. **取出 L1 要比对的标识串**（§6.2：`confirmation` 必须等于该用户的 email，
//     且**服务端自己查出来**再常数时间比对 —— 拿请求体里的 email 去比对自己，恒等于通过）。
//  2. **锁住这一行**（`FOR UPDATE`）。D10 要在「读余额 → 写分录 → 写缓存」之间
//     挡住并发的第二次调余额；不锁的话两个管理员同时点，两条分录都写成功、
//     `wallet_balances` 的 `balance + EXCLUDED.balance` 也各加一次，
//     账**是平的**（每条分录自己平），只是钱多了一倍 —— 没有任何巡检会报红。
//  3. **给出改前值**。D3 的 before 就是这里的 `sub_revoked_at`；D10 的 before
//     另外走 GetWalletOverview（余额是聚合，不是列）。
//
// ⚠️ 锁的是 **users** 而不是 `wallet_balances`：调余额时那一行**可能还不存在**
//
//	（新用户从没充过值，UpsertWalletBalance 走 INSERT 分支）。
//	对一行不存在的记录 `FOR UPDATE` 锁到的是空气，两个并发事务会双双通过。
//	users 那一行一定存在，所以它才是这条链路上唯一可靠的串行化点。
//
// ⚠️ `FOR UPDATE` 只在事务里有意义 —— 本条必须在 `audit.InTx` 给的事务里跑。
//
//	在池上裸跑它，锁在语句结束时就释放了，等于没锁。
func (q *Queries) LockAdminUserTarget(ctx context.Context, userID int64) (LockAdminUserTargetRow, error) {
	row := q.db.QueryRow(ctx, lockAdminUserTarget, userID)
	var i LockAdminUserTargetRow
	err := row.Scan(
		&i.ID,
		&i.Email,
		&i.Banned,
		&i.SubRevokedAt,
		&i.PlanID,
		&i.ExpiredAt,
		&i.CreatedAt,
	)
	return i, err
}

const resetAdminAccountTotp = `-- name: ResetAdminAccountTotp :one
WITH before AS (
  SELECT a.id, a.email, a.role, a.totp_confirmed_at, a.disabled_at
  FROM admin_users a
  WHERE a.id = $1::bigint
  FOR UPDATE
), upd AS (
  UPDATE admin_users a SET
    totp_secret_enc   = $2::bytea,
    totp_confirmed_at = now(),
    updated_at        = now()
  FROM before b
  WHERE a.id = b.id
  RETURNING a.id, a.email, a.totp_confirmed_at
)
SELECT
  b.totp_confirmed_at AS before_totp_confirmed_at,
  b.disabled_at       AS before_disabled_at,
  a.id, a.email,
  a.totp_confirmed_at AS after_totp_confirmed_at
FROM before b JOIN upd a ON a.id = b.id
`

type ResetAdminAccountTotpParams struct {
	AdminID       int64  `json:"admin_id"`
	TotpSecretEnc []byte `json:"totp_secret_enc"`
}

type ResetAdminAccountTotpRow struct {
	BeforeTotpConfirmedAt pgtype.Timestamptz `json:"before_totp_confirmed_at"`
	BeforeDisabledAt      pgtype.Timestamptz `json:"before_disabled_at"`
	ID                    int64              `json:"id"`
	Email                 string             `json:"email"`
	AfterTotpConfirmedAt  pgtype.Timestamptz `json:"after_totp_confirmed_at"`
}

// ---------- §2.5 重置 TOTP（resetAdminTotp，D15：L1 + L3） ----------
//
// 🔴 **改前/改后值里绝对不能出现 secret 本身**（无论明文还是密文）。
//
//	`audit_logs` 是 append-only、永不删除的表，一份写进去的凭据就是**永久**写进去的。
//	密文也不行：密钥在 Secret Manager，而审计表可能被导出、被拷进工单、被贴进聊天窗口。
//	所以本条 RETURNING 里**只有时间戳**：审计能证明「谁在什么时候给谁换了钥匙」，
//	这已经是这条记录需要回答的全部问题。
//	⚠️ 同理，新 secret 的明文只出现在 200 响应体里（openapi 的 TotpEnrollment），
//	   出现且仅出现一次，不落库、不进日志。
//
// ⚠️ **刻意不清理该管理员的 `used_totp` 行**。旧 secret 生成的码对新 secret 一律验不过，
//
//	留着不构成重放风险；而它们最多在 10 分钟后被 `CleanupUsedTotp` 扫掉（0015 的窗口）。
//	唯一的理论代价：新 secret 的第一个码恰好与 10 分钟内用过的某个 6 位数相同时会被误拒一次
//	—— 概率 ~1e-6 量级，代价是用户等 30 秒。为它多加一条 DELETE 不值得，
//	而**多一条 DELETE 就多一条「谁能删 used_totp」的路径**。
//
// ⚠️ `totp_confirmed_at` 直接写 now()，因为它 NOT NULL、库里不存在「待确认」状态（见 §2.3）。
//
//	这意味着重置的那一刻旧钥匙立刻失效、新钥匙立刻生效 —— 中间**没有**「两把钥匙都能用」
//	的过渡窗口。所以后台必须先把二维码交到本人手上再点确认，
//	顺序错了那个人就进不来了（而他自己没有任何自助恢复入口）。
func (q *Queries) ResetAdminAccountTotp(ctx context.Context, arg ResetAdminAccountTotpParams) (ResetAdminAccountTotpRow, error) {
	row := q.db.QueryRow(ctx, resetAdminAccountTotp, arg.AdminID, arg.TotpSecretEnc)
	var i ResetAdminAccountTotpRow
	err := row.Scan(
		&i.BeforeTotpConfirmedAt,
		&i.BeforeDisabledAt,
		&i.ID,
		&i.Email,
		&i.AfterTotpConfirmedAt,
	)
	return i, err
}

const updateAdminNotice = `-- name: UpdateAdminNotice :one
WITH before AS (
  SELECT n.id, n.title, n.content_md, n.pinned, n.visible, n.starts_at, n.ends_at, n.sort_order
  FROM notices n
  WHERE n.id = $1::bigint
  FOR UPDATE
), upd AS (
  UPDATE notices n SET
    title      = $2::text,
    content_md = $3::text,
    pinned     = coalesce($4::boolean,        n.pinned),
    starts_at  = coalesce($5::timestamptz, n.starts_at),
    updated_at = now()
  FROM before b
  WHERE n.id = b.id
  RETURNING n.id, n.title, n.content_md, n.level, n.pinned, n.visible,
            n.starts_at, n.ends_at, n.sort_order, n.created_by, n.created_at, n.updated_at
)
SELECT
  b.title      AS before_title,
  b.content_md AS before_content_md,
  b.pinned     AS before_pinned,
  b.starts_at  AS before_starts_at,
  a.id, a.title, a.content_md, a.level, a.pinned, a.visible,
  a.starts_at, a.ends_at, a.sort_order, a.created_by,
  coalesce(a.starts_at, a.created_at)::timestamptz AS published_at,
  a.created_at, a.updated_at
FROM before b JOIN upd a ON a.id = b.id
`

type UpdateAdminNoticeParams struct {
	NoticeID  int64              `json:"notice_id"`
	Title     string             `json:"title"`
	ContentMd string             `json:"content_md"`
	Pinned    *bool              `json:"pinned"`
	StartsAt  pgtype.Timestamptz `json:"starts_at"`
}

type UpdateAdminNoticeRow struct {
	BeforeTitle     string             `json:"before_title"`
	BeforeContentMd string             `json:"before_content_md"`
	BeforePinned    bool               `json:"before_pinned"`
	BeforeStartsAt  pgtype.Timestamptz `json:"before_starts_at"`
	ID              int64              `json:"id"`
	Title           string             `json:"title"`
	ContentMd       string             `json:"content_md"`
	Level           string             `json:"level"`
	Pinned          bool               `json:"pinned"`
	Visible         bool               `json:"visible"`
	StartsAt        pgtype.Timestamptz `json:"starts_at"`
	EndsAt          pgtype.Timestamptz `json:"ends_at"`
	SortOrder       int32              `json:"sort_order"`
	CreatedBy       *int64             `json:"created_by"`
	PublishedAt     pgtype.Timestamptz `json:"published_at"`
	CreatedAt       pgtype.Timestamptz `json:"created_at"`
	UpdatedAt       pgtype.Timestamptz `json:"updated_at"`
}

// 编辑公告（updateAdminNotice，D12）。before/after 同 §1.4，理由不重复。
// ⚠️ **`NoticeUpsert` 的 title/content 是 required，所以这是 PUT 语义的 PATCH**：
//
//	两列无条件覆写，pinned 与 starts_at 走 coalesce（未传 = 不改）。
//	这个不对称是契约给的，不是本条的选择 —— 写在这里免得后人以为漏了 coalesce。
//
// ⚠️ 与 §1.4 一样，「把 starts_at 改回 NULL（立刻发布）」表达不出来。同一处契约缺口。
func (q *Queries) UpdateAdminNotice(ctx context.Context, arg UpdateAdminNoticeParams) (UpdateAdminNoticeRow, error) {
	row := q.db.QueryRow(ctx, updateAdminNotice,
		arg.NoticeID,
		arg.Title,
		arg.ContentMd,
		arg.Pinned,
		arg.StartsAt,
	)
	var i UpdateAdminNoticeRow
	err := row.Scan(
		&i.BeforeTitle,
		&i.BeforeContentMd,
		&i.BeforePinned,
		&i.BeforeStartsAt,
		&i.ID,
		&i.Title,
		&i.ContentMd,
		&i.Level,
		&i.Pinned,
		&i.Visible,
		&i.StartsAt,
		&i.EndsAt,
		&i.SortOrder,
		&i.CreatedBy,
		&i.PublishedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const updateAdminSettingsValues = `-- name: UpdateAdminSettingsValues :many
WITH patch AS (
  SELECT k.key, v.val::jsonb AS value
  FROM unnest($1::text[])   WITH ORDINALITY AS k(key, n)
  JOIN unnest($2::text[]) WITH ORDINALITY AS v(val, n) ON v.n = k.n
), before AS (
  SELECT s.key, s.value
  FROM settings s JOIN patch p ON p.key = s.key
), upd AS (
  UPDATE settings s SET
    value      = p.value,
    updated_by = $3::bigint,
    updated_at = now()
  FROM patch p
  WHERE s.key = p.key
  RETURNING s.key, s.value, s.updated_at
)
SELECT b.key,
       b.value AS before_value,
       a.value AS after_value,
       a.updated_at
FROM before b JOIN upd a ON a.key = b.key
ORDER BY b.key
`

type UpdateAdminSettingsValuesParams struct {
	SettingKeys   []string `json:"setting_keys"`
	SettingValues []string `json:"setting_values"`
	AdminUserID   int64    `json:"admin_user_id"`
}

type UpdateAdminSettingsValuesRow struct {
	Key         string             `json:"key"`
	BeforeValue []byte             `json:"before_value"`
	AfterValue  []byte             `json:"after_value"`
	UpdatedAt   pgtype.Timestamptz `json:"updated_at"`
}

// ---------- §5.2 改配置（updateAdminSettings，D13：L2 必填原因） ----------
//
// 🔴 **UPDATE 不是 UPSERT：只改已存在的键，不认识的键一条都不写。**
//
//	`settings.key` 是自由文本主键，没有任何白名单表。写成 `INSERT … ON CONFLICT DO UPDATE`
//	的话，一次手滑的 `{"expire_remid": ...}` 会**静默地新建**一个永远不会被读到的键，
//	而真正想改的那个原封不动 —— 页面显示「已保存」，行为没有任何变化。
//	改成纯 UPDATE 之后，那次手滑影响 0 行，handler 靠
//	🔴 **`len(rows) == 传入键数` 这条断言**把它翻成 422 并列出哪些键不认识。
//	代价：新增配置项必须走迁移（`INSERT INTO settings … description`）。
//	这是对的 —— 一个配置项的**说明**（description 是 NOT NULL）本来就该跟着它的引入一起写。
//
// 🔴 **两个数组按下标配对，不用 `jsonb_each`。** 两条理由：
//
//	· sqlc v1.31 的内建 catalog 对返回 setof record 的 json 函数支持不确定，
//	  而本仓库已经证明 `unnest(...) WITH ORDINALITY` 这条路可用（stats.sql 三处在跑）；
//	· 值以 text 传入再 `::jsonb` 转换，非法 JSON 在**这一步**就抛 22P02 整条回滚，
//	  而不是变成一个存进库里、下次启动时才炸的坏值。
//	⚠️ 调用方必须保证两个数组等长（Go 侧 assert）。不等长时 JOIN 会静默丢掉多出来的那些，
//	  而现象是「有几个配置没保存上」，没有任何报错。
//	⚠️ 参数名是 `setting_keys` / `setting_values` 而不是 `keys` / `values`：
//	  `VALUES` 是 PostgreSQL 的保留字，`sqlc.arg(values)` 这种写法把一个保留字放进
//	  标识符位置 —— 实测当前版本能解析，但它依赖的是「函数实参位置的宽松处理」这条
//	  随时可能收紧的行为。为一个零成本的改名保留这种依赖不值得。
//
// ⚠️ before/after 同 §1.4 的一条语句两 CTE：`before` 读的是 UPDATE 之前的快照。
//
//	D13 的审计要记**每一个被改的键的新旧值**（不是「改了 5 个键」这种摘要）——
//	配置回滚时唯一能用的东西就是这份逐键旧值。
func (q *Queries) UpdateAdminSettingsValues(ctx context.Context, arg UpdateAdminSettingsValuesParams) ([]UpdateAdminSettingsValuesRow, error) {
	rows, err := q.db.Query(ctx, updateAdminSettingsValues, arg.SettingKeys, arg.SettingValues, arg.AdminUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UpdateAdminSettingsValuesRow{}
	for rows.Next() {
		var i UpdateAdminSettingsValuesRow
		if err := rows.Scan(
			&i.Key,
			&i.BeforeValue,
			&i.AfterValue,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAdminUserEntitlement = `-- name: UpdateAdminUserEntitlement :one
WITH before AS (
  SELECT u.id, u.email, u.uuid, u.group_id, u.plan_id, u.expired_at, u.device_limit,
         u.speed_limit_mbps, u.transfer_enable_plan, u.transfer_enable_pack, u.transfer_enable
  FROM users u
  WHERE u.id = $1::bigint AND u.deleted_at IS NULL
  FOR UPDATE
), upd AS (
  UPDATE users u SET
    expired_at   = coalesce($2::timestamptz, u.expired_at),
    device_limit = coalesce($3::integer,   u.device_limit),
    group_id     = coalesce($4::bigint,        u.group_id),
    uuid         = coalesce($5::uuid,          u.uuid),
    -- 总额 − 加油包分量；未传时保持原值。见上面的三步推理。
    transfer_enable_plan = coalesce(
      $6::bigint - u.transfer_enable_pack,
      u.transfer_enable_plan),
    updated_at = now()
  FROM before b
  WHERE u.id = b.id
  RETURNING u.id, u.email, u.uuid, u.group_id, u.plan_id, u.expired_at, u.device_limit,
            u.speed_limit_mbps, u.transfer_enable_plan, u.transfer_enable_pack, u.transfer_enable
)
SELECT
  b.uuid                 AS before_uuid,
  b.group_id             AS before_group_id,
  b.expired_at           AS before_expired_at,
  b.device_limit         AS before_device_limit,
  b.transfer_enable_plan AS before_transfer_enable_plan,
  b.transfer_enable_pack AS before_transfer_enable_pack,
  b.transfer_enable      AS before_transfer_enable,
  a.id, a.email,
  a.uuid                 AS after_uuid,
  a.group_id             AS after_group_id,
  a.plan_id              AS after_plan_id,
  a.expired_at           AS after_expired_at,
  a.device_limit         AS after_device_limit,
  a.speed_limit_mbps     AS after_speed_limit_mbps,
  a.transfer_enable_plan AS after_transfer_enable_plan,
  a.transfer_enable_pack AS after_transfer_enable_pack,
  a.transfer_enable      AS after_transfer_enable
FROM before b JOIN upd a ON a.id = b.id
`

type UpdateAdminUserEntitlementParams struct {
	UserID              int64              `json:"user_id"`
	ExpiredAt           pgtype.Timestamptz `json:"expired_at"`
	DeviceLimit         *int32             `json:"device_limit"`
	GroupID             *int64             `json:"group_id"`
	NewUuid             pgtype.UUID        `json:"new_uuid"`
	TransferEnableTotal *int64             `json:"transfer_enable_total"`
}

type UpdateAdminUserEntitlementRow struct {
	BeforeUuid               pgtype.UUID        `json:"before_uuid"`
	BeforeGroupID            int64              `json:"before_group_id"`
	BeforeExpiredAt          pgtype.Timestamptz `json:"before_expired_at"`
	BeforeDeviceLimit        *int32             `json:"before_device_limit"`
	BeforeTransferEnablePlan int64              `json:"before_transfer_enable_plan"`
	BeforeTransferEnablePack int64              `json:"before_transfer_enable_pack"`
	BeforeTransferEnable     int64              `json:"before_transfer_enable"`
	ID                       int64              `json:"id"`
	Email                    string             `json:"email"`
	AfterUuid                pgtype.UUID        `json:"after_uuid"`
	AfterGroupID             int64              `json:"after_group_id"`
	AfterPlanID              *int64             `json:"after_plan_id"`
	AfterExpiredAt           pgtype.Timestamptz `json:"after_expired_at"`
	AfterDeviceLimit         *int32             `json:"after_device_limit"`
	AfterSpeedLimitMbps      *int32             `json:"after_speed_limit_mbps"`
	AfterTransferEnablePlan  int64              `json:"after_transfer_enable_plan"`
	AfterTransferEnablePack  int64              `json:"after_transfer_enable_pack"`
	AfterTransferEnable      int64              `json:"after_transfer_enable"`
}

// ---------- §1.4 编辑用户（updateAdminUser，D1：L2 必填原因） ----------
//
// 🔴 **配额写 `transfer_enable_plan`，且是「总额 − 加油包分量」。** 三步推理：
//
//	· openapi 的 `AdminUserPatch.transfer_enable_bytes` 是**总额**（用户看到的那个数）；
//	· `users.transfer_enable` 是生成列，赋值会在运行时炸（0016:66，ADR 0013 §6.3）；
//	· 加油包分量 `_pack` 是用户**买过的东西**（ADR 0013 §5.1），管理员改总配额时
//	  不该把它悄悄抹掉。所以写成 `_plan = 请求的总额 − 当前 _pack`，
//	  结果的总额精确等于请求值，而 _pack 原封不动。
//	请求的总额小于当前 _pack 时，`transfer_enable_plan >= 0` 这条 CHECK 会拒绝（23514），
//	handler 把它翻成 422 并在 message 里写明「该用户有 N 字节加油包，总配额不能低于它」。
//	⚠️ 这是本文件里唯一一处 SQL 做算术的地方，因为它必须**原子**读到当前 _pack ——
//	   handler 先读再算会在两次调用之间被一次加油包购买插进来，结果是把刚买的包吃掉。
//
// 🔴 **before/after 用一条语句里的两个 CTE，不用「先读一份再改」。** 理由是语义而不是省一次往返：
//
//	同一条语句里，数据修改型 CTE **互相看不到对方的效果**（subscription_user.sql §2 逐字依赖的
//	正是这条语义），所以 `before` 读到的必然是这次 UPDATE 之前的快照，
//	而且**中间不存在任何时刻**能让第三方改动它。
//	换成「先 SELECT 再 UPDATE」两条语句：即使在同一个事务里，两者之间也能插进
//	一次并发的 D1（另一个管理员、或一次订单开通的 ApplyUserEntitlement），
//	于是审计记下的 before 是一个**从未紧接着 after 出现过**的状态 —— 而审计的全部用途
//	就是事后重建「谁把什么改成了什么」。一条记着假 before 的审计比没有审计更坏。
//
// ⚠️ **PATCH 的「置空」表达不出来**（契约缺口，登记在此）：
//
//	`expired_at` 与 `device_limit` 的 NULL 都是有意义的值（不限时 / 不限设备），
//	而 JSON 里「字段缺席」与「字段为 null」在 oapi-codegen 生成的 `*T` 上都是 nil，
//	所以本条只能把 nil 理解成「不改」。**后果**：管理员无法通过 API 把一个用户改成不限时。
//	要补它需要在 openapi 里加显式的 `clear_expired_at: true` 之类的字段，而 openapi 已冻结。
//
// ⚠️ 改 `group_id` / `uuid` / `expired_at` / `transfer_enable_plan` / `device_limit`
//
//	都会触发 `users_bump_user_rev_trg`（0012 + 0016 的监视列表），节点最多 60 秒后生效。
//	这一条在 Go 代码里**完全看不见**（data-model §15.1 登记过这个代价），
//	所以写在这里：handler 不需要、也不应该再显式 bump 一次。
func (q *Queries) UpdateAdminUserEntitlement(ctx context.Context, arg UpdateAdminUserEntitlementParams) (UpdateAdminUserEntitlementRow, error) {
	row := q.db.QueryRow(ctx, updateAdminUserEntitlement,
		arg.UserID,
		arg.ExpiredAt,
		arg.DeviceLimit,
		arg.GroupID,
		arg.NewUuid,
		arg.TransferEnableTotal,
	)
	var i UpdateAdminUserEntitlementRow
	err := row.Scan(
		&i.BeforeUuid,
		&i.BeforeGroupID,
		&i.BeforeExpiredAt,
		&i.BeforeDeviceLimit,
		&i.BeforeTransferEnablePlan,
		&i.BeforeTransferEnablePack,
		&i.BeforeTransferEnable,
		&i.ID,
		&i.Email,
		&i.AfterUuid,
		&i.AfterGroupID,
		&i.AfterPlanID,
		&i.AfterExpiredAt,
		&i.AfterDeviceLimit,
		&i.AfterSpeedLimitMbps,
		&i.AfterTransferEnablePlan,
		&i.AfterTransferEnablePack,
		&i.AfterTransferEnable,
	)
	return i, err
}
